  /** Ali se artikel prodaja kot del menija; alkohol kljub temu ostane na splošni stopnji. */
  jeDelMenija?: boolean;
  /** Ali je artikel viden in naročljiv v javnem QR meniju. */
  qrNaVoljo?: boolean;
