  /**
     * ID prostora, v katerem stoji miza naročila (null če miza nima prostora ali naročilo nima mize)
     * @nullable
     */
  prostorId?: number | null;
  /**
     * Ime prostora, v katerem stoji miza naročila (null če miza nima prostora ali naročilo nima mize)
     * @nullable
     */
  prostorIme?: string | null;
  status: NarociloStatus;
  skupaj: number;
  /** Trenutna ločena napitnina odprtega QR naročila; ni del prodaje, postavk ali DDV. */
  znesekNapitnina?: number;
  /** @nullable */
  opomba?: string | null;
  /** Izvor naročila; telefonsko naročilo ni vezano na mizo. */
  nacin?: NarociloNacin;
  /** QR gost pomeni, da je naročilo oddal gost prek javnega menija na mizi. */
