  /** @nullable */
  strankaIme?: string | null;
  /** @nullable */
  strankaTelefon?: string | null;
  /** @nullable */
  shranjeniKupecId?: number | null;
  /** @nullable */
  predvidenPrevzem?: string | null;
  /** Čas prevzema je ročno nastavljen in se ne izračuna samodejno. */
