  /**
     * Trenutni operativni status dostave; izpolnjen je samo pri dostavnih naročilih.
     * @nullable
     */
  dostavaStatus?: NarociloDostavaStatus;
  /**
     * Kurir, povezan z dostavnim naročilom; lahko ostane zapisan tudi po deaktivaciji zaradi zgodovine.
     * @nullable
     */
  dostavaKurirId?: number | null;
  /**
     * Fizični naročnik iz šifranta naročnikov.
     * @nullable
     */
  narocnikId?: number | null;
  /** @nullable */
  dostavaUlica?: string | null;
  /** @nullable */
  dostavaHisnaStevilka?: string | null;
  /** @nullable */
  dostavaVhod?: string | null;
  /** @nullable */
  dostavaNadstropje?: string | null;
  /** @nullable */
  dostavaNaseljeNaziv?: string | null;
  /** @nullable */
  dostavaNaseljeId?: number | null;
  /** @nullable */
  dostavaNavodilo?: string | null;
  /**
     * Revizijski snapshot cene; zaračunani znesek je vedno v dostavni postavki.
     * @nullable
     */
  dostavaCena?: number | null;
  /** @nullable */
  dostavaCasMin?: number | null;
  /** @nullable */
  predvidenaDostava?: string | null;
  ustvarjeno: string;
  /** @nullable */
  posodobljeno?: string | null;
  postavke: Postavka[];
  /** Zgodovina prenosov naročila med mizami */
  prenosi: PrenosNarocila[];
  /** DDV neskladje — prisotno, kadar je neskladje med seštevkom DDV skupin in DDV na računu > 0.01 EUR */
